export function audioSyncMarkup(prefix = '') {
  const id = name => prefix + name;
  return `<details id="${id('audio-sync')}" class="audio-sync" hidden><summary>Sync audio &amp; MIDI <span>Find a match, then listen.</span></summary><div class="sync-body">
      <div class="sync-auto"><div><h4>Find a starting point</h4><p>Compare the recording’s attacks with your selected MIDI part. Analysis runs on this device. Use matching versions of the song.</p></div><div class="sync-auto-options"><label>Search around current offset<select id="${id('sync-window')}"><option value="60">±60 seconds</option><option value="12">±12 seconds</option></select></label><label class="sync-check"><input id="${id('sync-drift')}" type="checkbox" checked>Check tempo difference (±8% in duration)</label><button id="${id('suggest-sync')}" class="button secondary" type="button">Suggest alignment</button></div></div>
      <div id="${id('sync-candidates')}" class="sync-candidates"></div><p id="${id('sync-status')}" class="import-help" role="status"></p>
      <div class="sync-manual"><h4>Line up the notes and audio</h4><p class="import-help">Colored markers show the MIDI notes over the audio waveform. The rows below separate notes that strike together. Click a hit in a note row to select its MIDI bar and beat, then click the matching audio peak and choose <strong>Apply beat match</strong>. Gold lines mark bar starts; the gold cursor is your chosen recording time.</p>
        <div class="sync-fields"><label>MIDI bar<input id="${id('sync-bar')}" type="number" min="1" step="1" value="1"></label><label>MIDI beat<input id="${id('sync-beat')}" type="number" min="1" max="32.99" step="0.25" value="1"></label><label>Recording time <span>seconds</span><input id="${id('sync-audio')}" type="number" min="0" step="0.001" value="0"></label><label>Waveform window<select id="${id('sync-zoom')}"><option value="10">10 seconds</option><option value="2">2 seconds · fine</option><option value="30">30 seconds</option><option value="1200">Whole recording</option></select></label></div>
        <label class="sync-check sync-overlay-toggle"><input id="${id('sync-show-midi')}" type="checkbox" checked>Overlay MIDI notes</label>
        <canvas id="${id('sync-waveform')}" class="sync-waveform" height="140" aria-label="Audio waveform with MIDI note overlays and separate colored drum rows. Click a note-row marker to select a MIDI beat, then click the audio waveform to choose its recording time. The MIDI bar, MIDI beat, and Recording time fields offer the same controls." aria-describedby="${id('sync-overlay-help')} ${id('sync-note-selection')}"></canvas>
        <div id="${id('sync-midi-legend')}" class="sync-midi-legend" aria-label="MIDI note colors"></div><p id="${id('sync-overlay-help')}" class="import-help">Markers move with the current offset and MIDI speed. Use the 2-second window to align individual attacks more precisely.</p><p id="${id('sync-note-selection')}" class="import-help" role="status"></p>
        <label class="sync-check"><input id="${id('sync-second')}" type="checkbox">Use a second match to correct steady drift</label>
        <div id="${id('sync-second-fields')}" class="sync-second-fields" hidden><p class="import-help">Choose the same later beat in both files, preferably near the end. This fits one overall tempo difference; changing live tempo or different arrangements may need shorter practice sections.</p><div class="sync-fields"><label>Second MIDI bar<input id="${id('sync-bar-2')}" type="number" min="1" step="1" value="5"></label><label>Second MIDI beat<input id="${id('sync-beat-2')}" type="number" min="1" step="0.25" value="1"></label><label>Second recording time <span>seconds</span><input id="${id('sync-audio-2')}" type="number" min="0" step="0.001"></label></div></div>
        <div class="sync-buttons"><button id="${id('match-sync')}" class="button secondary" type="button">Apply beat match</button><button id="${id('audio-earlier')}" class="text-button" type="button">Audio 50 ms earlier</button><button id="${id('audio-later')}" class="text-button" type="button">Audio 50 ms later</button></div>
        <p id="${id('sync-summary')}" class="import-help"></p><div class="sync-buttons"><button id="${id('preview-audio')}" class="button secondary" type="button">Hear recording here</button><button id="${id('preview-sync')}" class="button primary" type="button">Preview together · 8 sec</button><button id="${id('stop-sync')}" class="text-button" type="button" disabled>Stop preview</button><label class="sync-check"><input id="${id('sync-guide')}" type="checkbox" checked>Guide notes</label></div><p id="${id('sync-preview-state')}" class="import-help" role="status"></p>
      </div></div></details>`;
}
